S=[]
S.append(TITLE('TIN HỌC · PYTHON 5','ĐỘ PHỨC TẠP<br>THUẬT TOÁN','Đếm phép toán, kí hiệu O, các lớp độ phức tạp, vòng lặp lồng nhau, vòng lặp nhân đôi, tổng điều hoà, trường hợp xấu nhất, bộ nhớ, chọn thuật toán theo giới hạn đề.',['O(n)','O(n²)','O(log n)','n log n','2ⁿ']))
S.append(goals(c,B,['Hiểu <b>độ phức tạp</b> đo số phép toán theo cỡ dữ liệu n.','Đếm <b>số lần chạy</b> của vòng lặp đơn, lồng, nhân đôi, phụ thuộc.','Dùng <b>kí hiệu O</b> và quy tắc bỏ hằng số, bỏ số hạng thấp.','Ước lượng <b>thời gian chạy</b> từ giới hạn đề bài (≈ 10⁸ phép/giây).','Phân biệt <b>trường hợp tốt nhất, trung bình, xấu nhất</b>; <b>độ phức tạp bộ nhớ</b>.'],['Khái niệm','Đếm phép toán','Các lớp độ phức tạp','Chọn thuật toán theo đề','Tự kiểm tra, HSG']))
S.append(S2(c,B+' · 1','Vì sao cần đo độ phức tạp?',card('Hai chương trình đúng, một cái quá chậm',P('Cùng một bài, <b>hai thuật toán đều đúng</b> nhưng một cái chạy 1 giây, cái kia chạy cả giờ khi n lớn.','Đo bằng giây <b>phụ thuộc máy</b>; nên ta đếm <b>số phép toán cơ bản</b> theo cỡ dữ liệu <b>n</b>.','<b>Độ phức tạp thời gian</b> = cách số phép toán <b>tăng</b> khi n tăng.')),CODE('def tong_cap(n):\n    t = 0\n    for i in range(1, n + 1):\n        t += i\n    return t\n\ndef tong_ct(n):\n    return n * (n + 1) // 2\n\nprint(tong_cap(10**6), tong_ct(10**6))',22)+R('def tong_cap(n):\n    t = 0\n    for i in range(1, n + 1):\n        t += i\n    return t\ndef tong_ct(n):\n    return n * (n + 1) // 2\nprint(tong_cap(10**6), tong_ct(10**6))','',22,'Cùng kết quả')+KEY('Cách 1: <b>n</b> phép cộng (O(n)). Cách 2: <b>vài</b> phép tính (O(1)). Với n = 10¹⁸, cách 1 không thể chạy xong.')))
S.append(S2(c,B+' · 1','Đếm số phép toán: vòng lặp đơn',card('Quy tắc',P('Vòng <code>for i in range(n)</code> chạy <b>n lần</b>; mỗi lần thực hiện số phép không đổi → tổng <b>≈ n</b>.','Hai vòng lặp <b>nối tiếp</b> (không lồng): <b>cộng</b> số lần: n + n = 2n.','Hai vòng <b>lồng nhau</b>: <b>nhân</b>: n × n = n².')),CODE('n = 1000\ndem = 0\nfor i in range(n):\n    dem += 1\nfor i in range(n):\n    dem += 1\nprint(dem)\ndem = 0\nfor i in range(n):\n    for j in range(n):\n        dem += 1\nprint(dem)',20)+R('n = 1000\ndem = 0\nfor i in range(n):\n    dem += 1\nfor i in range(n):\n    dem += 1\nprint(dem)\ndem = 0\nfor i in range(n):\n    for j in range(n):\n        dem += 1\nprint(dem)','',24,'Nối tiếp: 2n; lồng nhau: n²')))
S.append(S2(c,B+' · 1','Kí hiệu O: bỏ hằng số và số hạng thấp',card('Quy tắc đơn giản hoá',P('Chỉ giữ <b>số hạng lớn nhất</b> khi n lớn và <b>bỏ hệ số</b>.','3n² + 5n + 20 → <b>O(n²)</b>; 100n → <b>O(n)</b>; n + log n → <b>O(n)</b>; n log n + n² → <b>O(n²)</b>.','O là <b>cận trên</b>: nói thuật toán “không chậm hơn cỡ” đó.')),TB_ if False else T(tr('Số phép đếm được','Độ phức tạp',h=True)+tr('5n + 3','<b>O(n)</b>')+tr('n² + 1000n','<b>O(n²)</b>')+tr('2n + n²/2','<b>O(n²)</b>')+tr('7','<b>O(1)</b>')+tr('n log n + n','<b>O(n log n)</b>'))+KEY('Hệ số 100 hay 1000 không đổi <b>cấp</b> độ phức tạp: khi n đủ lớn, n² luôn lấn át 1000n.')))
# đếm tổng quát
S.append(S2(c,B+' · 2','Vòng lặp lồng phụ thuộc: n(n+1)/2',card('Tính tay',P('<code>for i in range(n): for j in range(i, n)</code>: vòng j chạy <b>n − i</b> lần.','Tổng = n + (n−1) + … + 1 = <b>n(n+1)/2</b>. Với n = 10: <b>55</b>.','Bậc vẫn là <b>O(n²)</b>.')),CODE('n = 10\ndem = 0\nfor i in range(n):\n    for j in range(i, n):\n        dem += 1\nprint(dem)\ns = 0\nfor i in range(1, 6):\n    for j in range(i):\n        s += 1\nprint(s)',22)+R('n = 10\ndem = 0\nfor i in range(n):\n    for j in range(i, n):\n        dem += 1\nprint(dem)\ns = 0\nfor i in range(1, 6):\n    for j in range(i):\n        s += 1\nprint(s)','',24,'55 và 15')+KEY('Vòng thứ hai: 1 + 2 + 3 + 4 + 5 = 15.')))
S.append(TB(c,B+' · 2','Bảng đếm: j chạy từ i đến n − 1 (n = 5)',['i','j chạy','số lần','cộng dồn'],[['0','0,1,2,3,4','5','5'],['1','1,2,3,4','4','9'],['2','2,3,4','3','12'],['3','3,4','2','14'],['4','4','1','15']],note=KEY('15 = 5×6/2. Mẹo: <b>nửa hình vuông</b> n × n (tam giác) → n²/2.')))
S.append(S2(c,B+' · 2','Vòng lặp nhân đôi: log n',card('i *= 2 hay n //= 2',P('Mỗi vòng, i <b>gấp đôi</b> (hoặc n giảm một nửa) → chỉ cần <b>log₂ n</b> vòng để đạt n.','n = 16: i = 1, 2, 4, 8 → <b>4 vòng</b> (i = 16 không còn &lt; n).','n = 10⁹ chỉ cần <b>30</b> vòng: lí do tìm kiếm nhị phân rất nhanh.')),CODE('n = 16\ndem = 0\ni = 1\nwhile i < n:\n    dem += 1\n    i *= 2\nprint(dem)\nm = 10**9\nk = 0\nwhile m > 0:\n    m //= 2\n    k += 1\nprint(k)',20)+R('n = 16\ndem = 0\ni = 1\nwhile i < n:\n    dem += 1\n    i *= 2\nprint(dem)\nm = 10**9\nk = 0\nwhile m > 0:\n    m //= 2\n    k += 1\nprint(k)','',22,'Kết quả')))
S.append(S2(c,B+' · 2','Vòng lặp lồng: n lần log n',card('n log n',P('Vòng ngoài n lần, vòng trong <b>nhân đôi</b> j: mỗi lượt log n → tổng <b>O(n log n)</b>.','Đặc trưng của <b>sắp xếp trộn, sắp xếp nhanh, heapsort</b>.')),CODE('n = 1024\nops = 0\nfor i in range(n):\n    j = 1\n    while j < n:\n        ops += 1\n        j *= 2\nprint(ops, n * 10)',22)+R('n = 1024\nops = 0\nfor i in range(n):\n    j = 1\n    while j < n:\n        ops += 1\n        j *= 2\nprint(ops, n * 10)','',24,'Kết quả (log₂1024 = 10)')))
S.append(S2(c,B+' · 2','Tổng điều hoà: n/1 + n/2 + … = n log n',card('Vòng lặp bước nhảy',P('<code>for j in range(i, n+1, i)</code> chạy <b>n / i</b> lần.','Tổng qua mọi i: <b>n(1 + 1/2 + 1/3 + … + 1/n) ≈ n ln n</b> → <b>O(n log n)</b>.','Gặp ở <b>sàng Eratosthenes</b>.')),CODE('n = 12\ndem = 0\nfor i in range(1, n + 1):\n    for j in range(i, n + 1, i):\n        dem += 1\nprint(dem)\nprint(sum(n // i for i in range(1, n + 1)))',22)+R('n = 12\ndem = 0\nfor i in range(1, n + 1):\n    for j in range(i, n + 1, i):\n        dem += 1\nprint(dem)\nprint(sum(n // i for i in range(1, n + 1)))','',24,'Kết quả')+KEY('12 + 6 + 4 + 3 + 2 + 2 + 1 + 1 + 1 + 1 + 1 + 1 = <b>35</b>. Cũng là tổng số ước của 1..12.')))
S.append(S2(c,B+' · 2','Lồng nhau mà vẫn O(n): kĩ thuật hai con trỏ',card('Đừng kết luận vội',P('Có <b>vòng while trong vòng for</b> nhưng biến j <b>chỉ tăng, không quay lại</b>: tổng số lần j tăng không quá n.','Tổng: <b>O(n)</b> chứ không phải O(n²).','Cần xem <b>tổng số lần thực hiện</b>, đừng chỉ nhìn hình dạng mã.')),CODE('n = 1000\nops = 0\nj = 0\nfor i in range(n):\n    while j < i:\n        j += 1\n        ops += 1\n    ops += 1\nprint(ops)',22)+R('n = 1000\nops = 0\nj = 0\nfor i in range(n):\n    while j < i:\n        j += 1\n        ops += 1\n    ops += 1\nprint(ops)','',24,'Kết quả: gần 2n, không phải n²')))
S.append(S2(c,B+' · 2','Vòng lặp trong vòng lặp có điều kiện',card('Bài HSG: số lần phép d += 1',P('Vòng ngoài: i = n, n/2, n/4, … → <b>log₂ n + 1</b> vòng. Mỗi vòng, vòng trong luôn chạy <b>n lần</b>.','Tổng ≈ <b>n × (số lần chia đôi)</b> → <b>O(n log n)</b>.')),CODE('def dem_phep(n):\n    d = 0\n    i = n\n    while i > 0:\n        j = 0\n        while j < n:\n            d += 1\n            j += 1\n        i //= 2\n    return d\nprint(dem_phep(8), dem_phep(16), dem_phep(32))',20)+R('def dem_phep(n):\n    d = 0\n    i = n\n    while i > 0:\n        j = 0\n        while j < n:\n            d += 1\n            j += 1\n        i //= 2\n    return d\nprint(dem_phep(8), dem_phep(16), dem_phep(32))','',22,'Kết quả')+KEY('n = 8: i = 8, 4, 2, 1 → 4 vòng × 8 = <b>32</b>. n = 16: 5 × 16 = <b>80</b>. n = 32: 6 × 32 = <b>192</b>.')))
# các lớp
S.append(TB(c,B+' · 3','Các lớp độ phức tạp thường gặp',['Lớp','Tên','Ví dụ','n = 10⁵: số phép'],[['O(1)','hằng','công thức, truy cập a[i]','1'],['O(log n)','logarit','tìm kiếm nhị phân','≈ 17'],['O(n)','tuyến tính','duyệt dãy, tìm max','10⁵'],['O(n log n)','n log n','sắp xếp trộn, sort() của Python','≈ 1,7·10⁶'],['O(n²)','bình phương','hai vòng lồng, sắp xếp chọn','10¹⁰'],['O(2ⁿ)','mũ','liệt kê mọi tập con','không thể (n ≥ 40)'],['O(n!)','giai thừa','liệt kê mọi hoán vị','không thể (n ≥ 12)']],note=KEY('Thứ tự tăng: <b>1 &lt; log n &lt; n &lt; n log n &lt; n² &lt; n³ &lt; 2ⁿ &lt; n!</b>. Ba hàng cuối là “bùng nổ”.')))
S.append(S2(c,B+' · 3','Ước lượng thời gian chạy từ giới hạn đề',card('Quy tắc kinh nghiệm',P('Python làm khoảng <b>10⁷ phép/giây</b> (vòng lặp thuần), C++ khoảng <b>10⁸–10⁹</b>. Đề HSG thường cho <b>1–2 giây</b>.','Tính <b>số phép = độ phức tạp(n)</b>: nếu <b>vượt ~10⁷</b> với Python thì cần thuật toán tốt hơn.','Ví dụ n = 10⁵, O(n²) = <b>10¹⁰</b> → quá chậm; O(n log n) ≈ 1,7·10⁶ → được.')),TB_ if False else T(tr('Giới hạn n','Thuật toán tối đa chấp nhận được',h=True)+tr('n ≤ 20','O(2ⁿ) hoặc O(n!) nhỏ')+tr('n ≤ 1000','<b>O(n²)</b>')+tr('n ≤ 10⁵','<b>O(n log n)</b>')+tr('n ≤ 10⁶','<b>O(n)</b>')+tr('n ≤ 10¹⁸','<b>O(log n)</b> hoặc O(1)'))+KEY('Đọc <b>giới hạn n</b> trong đề là bước đầu tiên để chọn thuật toán.')))
S.append(S2(c,B+' · 3','Ví dụ: bài toán cặp tổng k',card('Ba cách giải một bài',P('Đếm cặp (i &lt; j) có a[i] + a[j] = k.','<b>Cách 1</b> hai vòng lồng: O(n²).','<b>Cách 2</b> sắp xếp + hai con trỏ: O(n log n).','<b>Cách 3</b> dùng dict đếm: O(n).')),CODE('import time\ndef c1(a, k):\n    return sum(1 for i in range(len(a)) for j in range(i+1, len(a)) if a[i]+a[j]==k)\ndef c3(a, k):\n    d = {}; t = 0\n    for x in a:\n        t += d.get(k - x, 0)\n        d[x] = d.get(x, 0) + 1\n    return t\na = list(range(3000)) * 2\nprint(c1(a, 3000) == c3(a, 3000))',18)+R('def c1(a, k):\n    return sum(1 for i in range(len(a)) for j in range(i+1, len(a)) if a[i]+a[j]==k)\ndef c3(a, k):\n    d = {}; t = 0\n    for x in a:\n        t += d.get(k - x, 0)\n        d[x] = d.get(x, 0) + 1\n    return t\na = list(range(300)) * 2\nprint(c1(a, 300), c3(a, 300))','',22,'Hai cách cho cùng kết quả (n = 600)')+KEY('Với n = 10⁵: cách 1 mất ≈ 10¹⁰ phép — không kịp; cách 3 chỉ ≈ 10⁵.')))
S.append(S2(c,B+' · 3','Vì sao “x in list” chậm, “x in set” nhanh?',card('Chi phí các thao tác',T(tr('Thao tác','list','set / dict',h=True)+tr('<code>x in …</code>','O(n)','O(1) trung bình')+tr('thêm cuối','O(1)','O(1)')+tr('<code>a.pop(0)</code>','O(n)','—'))+P('“Có phần tử trùng”: set cho O(n), list cho O(n²).')),CODE('def trung(a, dung_set):\n    seen = set() if dung_set else []\n    for x in a:\n        if x in seen:\n            return True\n        seen.add(x) if dung_set else seen.append(x)\n    return False\nprint(trung([1, 2, 3, 1], True), trung([1, 2, 3], False))',20)+R('def trung(a, dung_set):\n    seen = set() if dung_set else []\n    for x in a:\n        if x in seen:\n            return True\n        seen.add(x) if dung_set else seen.append(x)\n    return False\nprint(trung([1, 2, 3, 1], True), trung([1, 2, 3], False))','',22,'Kết quả')+KEY('Dùng list: O(n²); dùng set: O(n).')))
S.append(S2(c,B+' · 3','Tốt nhất, trung bình, xấu nhất',card('Ba trường hợp',P('Tìm tuần tự x trong dãy n phần tử: <b>tốt nhất</b> 1 phép (x ở đầu); <b>trung bình</b> ≈ n/2; <b>xấu nhất</b> n (ở cuối hoặc không có).','Thường đánh giá theo <b>trường hợp xấu nhất</b> vì đó là <b>cận trên đảm bảo</b>.','<b>n/2 và n cùng bậc O(n)</b>: không phải hai độ phức tạp khác nhau.')),CODE('a = [7, 3, 9, 3, 5, 8]\ndef tim(a, k):\n    dem = 0\n    for i in range(len(a)):\n        dem += 1\n        if a[i] == k:\n            return i, dem\n    return -1, dem\nprint(tim(a, 7), tim(a, 3), tim(a, 8), tim(a, 4))',21)+R('a = [7, 3, 9, 3, 5, 8]\ndef tim(a, k):\n    dem = 0\n    for i in range(len(a)):\n        dem += 1\n        if a[i] == k:\n            return i, dem\n    return -1, dem\nprint(tim(a, 7), tim(a, 3), tim(a, 8), tim(a, 4))','',22,'(vị trí, số lần so sánh)')))
S.append(S2(c,B+' · 3','Độ phức tạp bộ nhớ',card('Không gian phụ',P('Đo lượng <b>bộ nhớ thêm</b> ngoài dữ liệu vào, theo n.','<b>O(1)</b>: chỉ vài biến (đảo danh sách bằng <b>hai chỉ số đổi chỗ</b> tại chỗ).','<b>O(n)</b>: tạo danh sách mới cùng cỡ; <b>đệ quy sâu n</b> cũng tốn O(n) ngăn xếp.','Đổi <b>thời gian lấy bộ nhớ</b> hoặc ngược lại (ví dụ dùng set để nhanh hơn).')),CODE('def dao_tai_cho(a):\n    i, j = 0, len(a) - 1\n    while i < j:\n        a[i], a[j] = a[j], a[i]\n        i += 1\n        j -= 1\n    return a\nprint(dao_tai_cho([1, 2, 3, 4, 5]))\nb = [1, 2, 3][::-1]\nprint(b)',22)+R('def dao_tai_cho(a):\n    i, j = 0, len(a) - 1\n    while i < j:\n        a[i], a[j] = a[j], a[i]\n        i += 1\n        j -= 1\n    return a\nprint(dao_tai_cho([1, 2, 3, 4, 5]))\nb = [1, 2, 3][::-1]\nprint(b)','',24,'Kết quả')+KEY('<code>a[::-1]</code> tạo bản sao nên tốn <b>O(n)</b> bộ nhớ; hai chỉ số chỉ <b>O(1)</b>.')))
S.append(S2(c,B+' · 3','Bùng nổ tổ hợp: 2ⁿ và n!',card('Vì sao vét cạn thất bại',P('Số tập con của n phần tử: <b>2ⁿ</b>. Với n = 40: <b>≈ 1,1 × 10¹²</b> (cần hàng giờ).','Số hoán vị: <b>n!</b>. Với n = 12: 479 001 600 (đã quá chậm với Python).','Giải pháp: <b>quy hoạch động</b>, <b>tham lam</b>, <b>chia để trị</b> hay <b>cắt tỉa</b>.')),CODE('print(2 ** 40)\nimport math\nprint(math.factorial(12), math.factorial(20))\nfrom itertools import combinations\nprint(sum(1 for r in range(5) for _ in combinations(range(4), r)))',22)+R('print(2 ** 40)\nimport math\nprint(math.factorial(12), math.factorial(20))\nfrom itertools import combinations\nprint(sum(1 for r in range(5) for _ in combinations(range(4), r)))','',24,'Kết quả (cuối: số tập con của 4 phần tử = 2⁴)')))
S.append(SELF(c,B+' · 4','Tự kiểm tra: đếm số lần lặp','Tính dem (không chạy máy) rồi kiểm tra.','n = 16\ndem = 0\ni = 1\nwhile i < n:\n    dem += 1\n    i *= 2\nprint(dem)',P('i nhận lần lượt 1, 2, 4, 8 (i &lt; 16 đúng); sau khi i = 8, i *= 2 → 16 không &lt; 16 nên dừng.','Vậy <b>dem = 4</b> (= log₂ 16). Độ phức tạp <b>O(log n)</b>.')+R('n = 16\ndem = 0\ni = 1\nwhile i < n:\n    dem += 1\n    i *= 2\nprint(dem)','',24,'Kết quả thật'),22))
S.append(SELF(c,B+' · 4','Tự kiểm tra (HSG): khoảng cách giá trị','Đoạn mã sau chạy bao nhiêu lần phép <code>ops += 1</code> với n = 12? Độ phức tạp là gì?','n = 12\nops = 0\nfor i in range(1, n + 1):\n    for j in range(i, n + 1, i):\n        ops += 1\nprint(ops)',P('Với mỗi i, vòng j chạy <b>⌊n / i⌋</b> lần: 12, 6, 4, 3, 2, 2, 1, 1, 1, 1, 1, 1.','Tổng = <b>35</b>. Tổng điều hoà ≈ n ln n → <b>O(n log n)</b>.')+R('n = 12\nops = 0\nfor i in range(1, n + 1):\n    for j in range(i, n + 1, i):\n        ops += 1\nprint(ops)','',24,'Kết quả thật'),22))
S.append(SELF(c,B+' · 4','Tự kiểm tra (HSG): chọn thuật toán','n = 10⁵ phần tử, giá trị a[i] ≤ 10⁴. Quy hoạch động f[i][v] (xét i phần tử, phần tử thứ i đặt thành v) cần khoảng bao nhiêu thao tác? Có chạy kịp 1–2 giây không?','n = 10**5\nV = 10**4\nprint(n * V)',P('Số trạng thái = n × V = 10⁵ × 10⁴ = <b>10⁹</b> thao tác.','Python chỉ làm khoảng 10⁷ phép/giây (kể cả C++ chỉ ≈ 10⁸–10⁹) nên <b>không kịp</b>; cần <b>cải tiến</b> (tối ưu chuyển trạng thái, nén trạng thái, đổi hướng thuật toán).')+R('n = 10**5\nV = 10**4\nprint(n * V)','',24,'Kết quả thật'),22))
S+=END(c,B,['Độ phức tạp là cách số phép toán <b>tăng theo n</b>; kí hiệu <b>O</b> giữ số hạng lớn nhất, bỏ hệ số.','Nối tiếp thì <b>cộng</b>, lồng nhau thì <b>nhân</b>; vòng nhân đôi cho <b>log n</b>.','Vòng lồng phụ thuộc: tổng <b>n(n+1)/2</b> (O(n²)); bước nhảy i cho <b>n log n</b>.','<b>Hai con trỏ</b> có thể O(n) dù lồng nhau.','Đánh giá theo <b>trường hợp xấu nhất</b>; n/2 và n cùng bậc.','Ước lượng thời gian: Python ≈ 10⁷ phép/giây → chọn thuật toán theo <b>giới hạn n</b>.'],[('Nhân đôi','O(log n)'),('Hai vòng lồng','O(n²)'),('Mọi tập con','2ⁿ'),('x in set','O(1)')],'Kết luận lồng nhau là O(n²) mà không đếm tổng; quên <b>log</b> của vòng nhân đôi.',['<code>a.pop(0)</code>, <code>a.insert(0, x)</code> là O(n).','<code>x in list</code> là O(n), <code>x in set</code> là O(1).','<code>sorted</code> là O(n log n).','Nên giữ <b>bộ nhớ</b> trong giới hạn đề (thường 256 MB).'],['<b>Độ phức tạp khấu hao</b> (amortized) của append.','<b>Định lí thợ</b> (Master theorem) cho đệ quy.','<b>NP-đầy đủ</b> và lớp bài khó.'],
 [('Một vòng for n lần chứa một vòng for n lần: độ phức tạp?',),('<code>i *= 2</code> từ 1 đến n: bao nhiêu lần?',),('Độ phức tạp của sort() Python?',),('n = 40: O(2ⁿ) có chạy kịp không?',),('3n² + 5n: viết bằng O?',)],
 [('<b>O(n²)</b>.',),('<b>log₂ n</b> lần.',),('<b>O(n log n)</b>.',),('<b>Không</b> (≈ 10¹²).',),('<b>O(n²)</b>.',)],
 [('Mức 1. Đếm số lần <code>dem += 1</code> với n = 7: <code>for i in range(n): for j in range(n): dem += 1</code>.',),('Mức 1. Độ phức tạp của đoạn tính tổng 1..n bằng vòng lặp và bằng công thức?',),('Mức 2. Đếm số lần chạy: <code>for i in range(1, n+1): j = i; while j &lt; n: j *= 2</code> (n = 64) và ước lượng độ phức tạp.',),('Mức 2. Bài “đếm phần tử khác nhau” với n = 10⁵ dùng list hay set? Giải thích.',),('Mức 3 (HSG). Với n = 20, đoạn <code>for i in range(n): for j in range(i+1, n): for k in range(j+1, n)</code> chạy bao nhiêu lần? Công thức tổng quát.',),('Mức 3 (HSG). Tính số lần chạy <code>s += 1</code>: <code>i = 1; while i &lt;= n: for j in range(i): s += 1; i *= 2</code> với n = 64, và độ phức tạp.',)],
 [('<b>49</b> lần (7²).',),('Vòng lặp: <b>O(n)</b>; công thức: <b>O(1)</b>.',),(V('n=64\nd=0\nfor i in range(1,n+1):\n    j=i\n    while j<n:\n        j*=2;d+=1\nprint(d)')+' lần; ≈ n log n (cận trên).',),('Dùng <b>set</b> → O(n); dùng list <code>in</code> → O(n²).',),(V('n=20\nd=0\nfor i in range(n):\n    for j in range(i+1,n):\n        for k in range(j+1,n): d+=1\nprint(d)')+' = C(20,3); tổng quát n(n−1)(n−2)/6 → O(n³).',),(V('n=64\ni=1;s=0\nwhile i<=n:\n    for j in range(i): s+=1\n    i*=2\nprint(s)')+' = 1 + 2 + 4 + … + 64 = 2n − 1 → O(n).',)],hper=2)
